      "function": "promotion",
      "proposition": "Dagger is a better way to ship software.",
      "support": "Lines 13–35 describe delivery features; comparative evidence is absent."
    },
    {
      "ordinal": 1,
      "function": "definition",
      "proposition": "Dagger is a software delivery automation platform.",
      "support": "Lines 15–35 describe its execution engine, API, SDKs, containers, caching, and tracing."
    },
    {
      "ordinal": 2,
      "function": "capability",
      "proposition": "Dagger can build, test, and ship any codebase reliably and at scale.",
      "support": "Line 19 describes repeatability mechanisms and names tests, builds, and deployments; evidence for any codebase and scale is absent."
    },
    {
      "ordinal": 3,
      "function": "capability",
      "proposition": "Dagger runs locally, on a CI server, or directly in the cloud.",
      "support": "Line 17 lists supported environments; line 33 requires a Linux container runtime."
    },
    {
      "ordinal": 4,
      "function": "transition",
      "proposition": "",
      "support": "Introduces the reasons described in lines 13–21."
    },
    {
      "ordinal": 5,
      "function": "capability",
      "proposition": "Dagger makes software delivery programmable, local-first, repeatable, and observable.",
      "support": "Lines 15–21 explain each property through APIs, supported environments, execution isolation, caching, and tracing."
    },
    {
      "ordinal": 6,
      "function": "capability",
      "proposition": "Dagger makes software delivery programmable.",
      "support": "Line 15 lists an execution engine, system API, SDKs for 8 languages, an interactive REPL, and reusable modules."
    },
    {
      "ordinal": 7,
      "function": "promotion",
      "proposition": "Shell scripts and proprietary YAML are no longer acceptable for software delivery automation.",
      "support": "absent"
    },
    {
      "ordinal": 8,
      "function": "capability",
      "proposition": "Dagger provides a complete execution engine, system API, SDKs for 8 languages, an interactive REPL, a rich reusable-module ecosystem, and more.",
      "support": "Lines 25–27 describe the API and name 8 SDK languages; evidence for engine completeness, the REPL, ecosystem richness, and unspecified additions is absent."
    },
    {
      "ordinal": 9,
      "function": "capability",
      "proposition": "Dagger makes software delivery local-first.",
      "support": "Line 17 says automated tasks run on supported laptops and other environments with a container runtime."
    },
    {
      "ordinal": 10,
      "function": "capability",
      "proposition": "Once automated with Dagger, a task reliably runs on any supported laptop, AI sandbox, CI server, or dedicated cloud infrastructure.",
      "support": "Line 17 limits the claim to supported systems and requires a container runtime; line 33 specifies a Linux container runtime and supported operating environments."
    },
    {
      "ordinal": 11,
      "function": "qualification",
      "proposition": "A container runtime such as Docker is the only dependency.",
      "support": "Line 33 specifies that the runtime must support Linux containers and describes Linux, macOS, and Windows execution."
    },
    {
      "ordinal": 12,
      "function": "capability",
      "proposition": "Dagger makes software delivery repeatable.",
      "support": "Line 19 describes containers, sandboxed functions, explicit typed host dependencies, just-in-time artifacts, and incremental operations."
    },
    {
      "ordinal": 13,
      "function": "capability",
      "proposition": "Tools execute in containers orchestrated by sandboxed functions.",
      "support": "Line 25 identifies container orchestration as a System API function; additional evidence for sandboxing is absent."
    },
    {
      "ordinal": 14,
      "function": "capability",
      "proposition": "Host dependencies are explicit and strictly typed.",
      "support": "Line 25 says every API operation is typed; specific evidence about host dependencies is absent."
    },
    {
      "ordinal": 15,
      "function": "capability",
      "proposition": "Intermediate artifacts are built just-in-time.",
      "support": "absent"
    },
