      "function": "capability",
      "proposition": "Every operation is incremental by default and has advanced cache control.",
      "support": "Line 31 describes input keys, selective re-execution, and automatic content-addressed caching; advanced cache controls are not specified."
    },
    {
      "ordinal": 17,
      "function": "promotion",
      "proposition": "Dagger produces trustworthy test reports, builds, and deployments.",
      "support": "Line 19 supplies containers, sandboxing, typed dependencies, just-in-time artifacts, and incremental execution as context; trustworthiness is not demonstrated."
    },
    {
      "ordinal": 18,
      "function": "capability",
      "proposition": "Dagger makes software delivery observable.",
      "support": "Lines 21 and 35 describe OpenTelemetry traces and spans, logs, metrics, trace visualization, and export."
    },
